vec2 v0 = b - a;
vec2 v1 = c - a;
vec2 v2 = p - a;
double denom = v0.x * v1.y - v1.x * v0.y;
double v = (v2.x * v1.y - v1.x * v2.y) / denom;
double w = (v0.x * v2.y - v2.x * v0.y) / denom;
double u = 1.0 - v - w;
return vec3(u, v, w);

